//! The Rust bindings of PostgreSQL's node structs, `NodeTag`, `List` and the
//! types their fields reference, and of PL/pgSQL's compiled-function structs
//! (`plpgsql.h`).
//!
//! `postgres/typedpg/bindings.rs` is generated by `import/import.sh` with
//! `bindgen` (see `import/README.md`); this module only includes it, with the
//! lints its C-derived names would otherwise trip.

#[allow(
    clippy::all,
    dead_code,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals
)]
mod generated {
    include!("../postgres/typedpg/bindings.rs");
}

pub(crate) use generated::*;
